    else if (!((ig_config.accept_threshold >= 0.0) &&
               (ig_config.accept_threshold < ig_config.reject_threshold))) invalid = 1;
    else if ((ig_config.max_consecutive_reject < 1U) ||
             (ig_config.max_consecutive_reject > 20U)) invalid = 1;
