if (ig_input.enable == 0) {
    ig_state.mode = IG_ACCEPT;
    ig_state.consecutive_reject = 0U;
    out.mode = IG_ACCEPT;
    out.consecutive_reject = 0U;
    out.nis = 0.0;
    out.whitened_norm = 0.0;
    out.use_measurement = 1;
    ig_output = out;
