    int enable_ok = (ig_input.enable == 1) ? 1 : 0;
    const adcs_vec3_t *res = ig_input.residual;
    const adcs_vec3_t *var = ig_input.variance;
    int finite_ok;
    adcs_vec3_t w;
    double nis, wnorm;

    finite_ok = (res != NULL) && (var != NULL) &&
                adcs_is_finite_vec3(res) && adcs_is_finite_vec3(var) &&
