                (var->x > 0.0) && (var->y > 0.0) && (var->z > 0.0) &&
                (ig_config.accept_threshold >= 0.0) &&
                (ig_config.accept_threshold < ig_config.reject_threshold) &&
                (ig_config.max_consecutive_reject >= 1U) &&
                (ig_config.max_consecutive_reject <= 20U);

    if (!enable_ok) {
        ig_state.mode = IG_ACCEPT;
        ig_state.consecutive_reject = 0U;
        ig_output.mode = IG_ACCEPT;
        ig_output.consecutive_reject = 0U;
        ig_output.nis = 0.0;
        ig_output.whitened_norm = 0.0;
        ig_output.use_measurement = 1;
        return;
    }

    if (!finite_ok) {
        ig_state.mode = IG_FAULT;
        ig_output.mode = IG_FAULT;
        ig_output.consecutive_reject = ig_state.consecutive_reject;
        ig_output.nis = INFINITY;
        ig_output.whitened_norm = INFINITY;
        ig_output.use_measurement = 0;
        return;
    }

    w.x = res->x / sqrt(var->x);
    w.y = res->y / sqrt(var->y);
    w.z = res->z / sqrt(var->z);
    nis = adcs_vec3_dot(&w, &w);
    wnorm = sqrt(nis);

    if (nis <= ig_config.accept_threshold) {
        ig_state.mode = IG_ACCEPT;
        ig_state.consecutive_reject = 0U;
    } else if (nis < ig_config.reject_threshold) {
        if (ig_state.mode == IG_REJECT) {
            ig_state.consecutive_reject += 1U;
        }
    } else {
        ig_state.mode = IG_REJECT;
        ig_state.consecutive_reject += 1U;
    }

    if (ig_state.consecutive_reject >= ig_config.max_consecutive_reject) {
        ig_state.mode = IG_FAULT;
    }

    ig_output.mode = ig_state.mode;
    ig_output.consecutive_reject = ig_state.consecutive_reject;
    ig_output.nis = nis;
    ig_output.whitened_norm = wnorm;
    ig_output.use_measurement = (ig_state.mode == IG_ACCEPT) ? 1 : 0;
}

